      REAL(dp), &
         DIMENSION(1*nl_a, 5*nl_b, 9*nl_c, 9*nl_d)       :: primitives
      REAL(dp), DIMENSION(1*6*15*15)                     :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
                                                            kmax, s_offset_a1, s_offset_b1, &
                                                            s_offset_c1, s_offset_d1

      s_offset_a1 = 0
