! **************************************************************************************************
   SUBROUTINE contract_pssg(work, &
                            nl_a, nl_b, nl_c, nl_d, &
                            sphi_a, sphi_b, sphi_c, sphi_d, &
                            primitives, &
                            buffer1, buffer2)
      REAL(dp), DIMENSION(3*1*1*15), INTENT(IN)          :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(3, 3*nl_a), INTENT(IN)         :: sphi_a
      REAL(dp), DIMENSION(1, 1*nl_b), INTENT(IN)         :: sphi_b
      REAL(dp), DIMENSION(1, 1*nl_c), INTENT(IN)         :: sphi_c
      REAL(dp), DIMENSION(15, 9*nl_d), INTENT(IN)        :: sphi_d
      REAL(dp), &
         DIMENSION(3*nl_a, 1*nl_b, 1*nl_c, 9*nl_d)       :: primitives
      REAL(dp), DIMENSION(3*1*1*15)                      :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
                                                            kmax, s_offset_a1, s_offset_b1, &
                                                            s_offset_c1, s_offset_d1

      s_offset_a1 = 0
      DO ia = 1, nl_a
         s_offset_b1 = 0
         DO ib = 1, nl_b
            s_offset_c1 = 0
            DO ic = 1, nl_c
               s_offset_d1 = 0
               DO id = 1, nl_d
                  buffer1 = 0.0_dp
                  imax = 1*1*15
                  kmax = 3
                  DO i = 1, imax
                     buffer1(i + imax*(3 - 1)) = buffer1(i + imax*(3 - 1)) + work(1 + (i - 1)*kmax)*sphi_a(1, 3 + s_offset_a1)
                     buffer1(i + imax*(1 - 1)) = buffer1(i + imax*(1 - 1)) + work(2 + (i - 1)*kmax)*sphi_a(2, 1 + s_offset_a1)
                     buffer1(i + imax*(2 - 1)) = buffer1(i + imax*(2 - 1)) + work(3 + (i - 1)*kmax)*sphi_a(3, 2 + s_offset_a1)
                  END DO
                  buffer2 = 0.0_dp
                  imax = 3*1*15
                  kmax = 1
                  DO i = 1, imax
                     buffer2(i + imax*(1 - 1)) = buffer2(i + imax*(1 - 1)) + buffer1(1 + (i - 1)*kmax)*sphi_b(1, 1 + s_offset_b1)
                  END DO
                  buffer1 = 0.0_dp
                  imax = 3*1*15
                  kmax = 1
                  DO i = 1, imax
                     buffer1(i + imax*(1 - 1)) = buffer1(i + imax*(1 - 1)) + buffer2(1 + (i - 1)*kmax)*sphi_c(1, 1 + s_offset_c1)
                  END DO
                  imax = 3*1*1
                  kmax = 15
                  i = 0
                  DO i1 = 1, 1
                  DO i2 = 1, 1
                  DO i3 = 1, 3
