      REAL(dp), DIMENSION(3*10*6*15), INTENT(IN)         :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(3, 3*nl_a), INTENT(IN)         :: sphi_a
      REAL(dp), DIMENSION(10, 7*nl_b), INTENT(IN)        :: sphi_b
      REAL(dp), DIMENSION(6, 5*nl_c), INTENT(IN)         :: sphi_c
      REAL(dp), DIMENSION(15, 9*nl_d), INTENT(IN)        :: sphi_d
      REAL(dp), &
         DIMENSION(3*nl_a, 7*nl_b, 5*nl_c, 9*nl_d)       :: primitives
      REAL(dp), DIMENSION(3*10*6*15)                     :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
                                                            kmax, s_offset_a1, s_offset_b1, &
                                                            s_offset_c1, s_offset_d1

      s_offset_a1 = 0
