                            primitives, &
                            buffer1, buffer2)
      REAL(dp), DIMENSION(6*6*3*10), INTENT(IN)          :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(6, 5*nl_a), INTENT(IN)         :: sphi_a
      REAL(dp), DIMENSION(6, 5*nl_b), INTENT(IN)         :: sphi_b
      REAL(dp), DIMENSION(3, 3*nl_c), INTENT(IN)         :: sphi_c
      REAL(dp), DIMENSION(10, 7*nl_d), INTENT(IN)        :: sphi_d
      REAL(dp), &
         DIMENSION(5*nl_a, 5*nl_b, 3*nl_c, 7*nl_d)       :: primitives
