         DIMENSION(5*nl_a, 5*nl_b, 7*nl_c, 3*nl_d)       :: primitives
      REAL(dp), DIMENSION(6*6*10*3)                      :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
