   SUBROUTINE contract_ddfg(work, &
                            nl_a, nl_b, nl_c, nl_d, &
                            sphi_a, sphi_b, sphi_c, sphi_d, &
                            primitives, &
                            buffer1, buffer2)
      REAL(dp), DIMENSION(6*6*10*15), INTENT(IN)         :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(6, 5*nl_a), INTENT(IN)         :: sphi_a
      REAL(dp), DIMENSION(6, 5*nl_b), INTENT(IN)         :: sphi_b
      REAL(dp), DIMENSION(10, 7*nl_c), INTENT(IN)        :: sphi_c
