                            sphi_a, sphi_b, sphi_c, sphi_d, &
                            primitives, &
                            buffer1, buffer2)
      REAL(dp), DIMENSION(6*6*15*6), INTENT(IN)          :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(6, 5*nl_a), INTENT(IN)         :: sphi_a
      REAL(dp), DIMENSION(6, 5*nl_b), INTENT(IN)         :: sphi_b
      REAL(dp), DIMENSION(15, 9*nl_c), INTENT(IN)        :: sphi_c
      REAL(dp), DIMENSION(6, 5*nl_d), INTENT(IN)         :: sphi_d
      REAL(dp), &
         DIMENSION(5*nl_a, 5*nl_b, 9*nl_c, 5*nl_d)       :: primitives
      REAL(dp), DIMENSION(6*6*15*6)                      :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
                                                            kmax, s_offset_a1, s_offset_b1, &
                                                            s_offset_c1, s_offset_d1

      s_offset_a1 = 0
      DO ia = 1, nl_a
         s_offset_b1 = 0
         DO ib = 1, nl_b
            s_offset_c1 = 0
            DO ic = 1, nl_c
               s_offset_d1 = 0
               DO id = 1, nl_d
                  buffer1 = 0.0_dp
                  imax = 6*15*6
                  kmax = 6
                  DO i = 1, imax
                     buffer1(i + imax*(3 - 1)) = buffer1(i + imax*(3 - 1)) + work(1 + (i - 1)*kmax)*sphi_a(1, 3 + s_offset_a1)
                     buffer1(i + imax*(5 - 1)) = buffer1(i + imax*(5 - 1)) + work(1 + (i - 1)*kmax)*sphi_a(1, 5 + s_offset_a1)
