                            sphi_a, sphi_b, sphi_c, sphi_d, &
                            primitives, &
                            buffer1, buffer2)
      REAL(dp), DIMENSION(6*15*1*3), INTENT(IN)          :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(6, 5*nl_a), INTENT(IN)         :: sphi_a
      REAL(dp), DIMENSION(15, 9*nl_b), INTENT(IN)        :: sphi_b
      REAL(dp), DIMENSION(1, 1*nl_c), INTENT(IN)         :: sphi_c
      REAL(dp), DIMENSION(3, 3*nl_d), INTENT(IN)         :: sphi_d
      REAL(dp), &
         DIMENSION(5*nl_a, 9*nl_b, 1*nl_c, 3*nl_d)       :: primitives
      REAL(dp), DIMENSION(6*15*1*3)                      :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
                                                            kmax, s_offset_a1, s_offset_b1, &
                                                            s_offset_c1, s_offset_d1

      s_offset_a1 = 0
