                  END DO
                  END DO
                  END DO
                  s_offset_d1 = s_offset_d1 + 1
               END DO
               s_offset_c1 = s_offset_c1 + 7
            END DO
            s_offset_b1 = s_offset_b1 + 9
         END DO
         s_offset_a1 = s_offset_a1 + 9
      END DO
   END SUBROUTINE contract_ggfs
