      REAL(dp), DIMENSION(15*15*10*3), INTENT(IN)        :: work
      INTEGER                                            :: nl_a, nl_b, nl_c, nl_d
      REAL(dp), DIMENSION(15, 9*nl_a), INTENT(IN)        :: sphi_a
      REAL(dp), DIMENSION(15, 9*nl_b), INTENT(IN)        :: sphi_b
      REAL(dp), DIMENSION(10, 7*nl_c), INTENT(IN)        :: sphi_c
      REAL(dp), DIMENSION(3, 3*nl_d), INTENT(IN)         :: sphi_d
      REAL(dp), &
         DIMENSION(9*nl_a, 9*nl_b, 7*nl_c, 3*nl_d)       :: primitives
      REAL(dp), DIMENSION(15*15*10*3)                    :: buffer1, buffer2

      INTEGER                                            :: i, i1, i2, i3, ia, ib, ic, id, imax, &
                                                            kmax, s_offset_a1, s_offset_b1, &
                                                            s_offset_c1, s_offset_d1

      s_offset_a1 = 0
      DO ia = 1, nl_a
         s_offset_b1 = 0
         DO ib = 1, nl_b
            s_offset_c1 = 0
